solution.javascript:
function alienOrder(words) {
  const adj = {}, indeg = {};
  for (const w of words) for (const c of w) { adj[c] = adj[c] || []; indeg[c] = indeg[c] || 0; }
  for (let i = 0; i < words.length - 1; i++) {
    const a = words[i], b = words[i+1];
    if (a.length > b.length && a.startsWith(b)) return '';
    for (let j = 0; j < Math.min(a.length, b.length); j++) {
      if (a[j] !== b[j]) { adj[a[j]].push(b[j]); indeg[b[j]]++; break; }
    }
  }
  const q = Object.keys(indeg).filter(c => indeg[c] === 0);
  let result = '';
  while (q.length) {
    const c = q.shift(); result += c;
    for (const n of adj[c]) if (--indeg[n] === 0) q.push(n);
  }
  return result.length === Object.keys(indeg).length ? result : '';
}

solution.cpp:
string alienOrder(vector<string>& words) {
    unordered_map<char, vector<char>> adj;
    unordered_map<char, int> indeg;
    for (auto& w : words) for (char c : w) { adj[c]; indeg[c]; }
    for (int i = 0; i < words.size()-1; i++) {
        string a = words[i], b = words[i+1];
        if (a.size() > b.size() && a.substr(0, b.size()) == b) return "";
        for (int j = 0; j < min(a.size(), b.size()); j++) {
            if (a[j] != b[j]) { adj[a[j]].push_back(b[j]); indeg[b[j]]++; break; }
        }
    }
    queue<char> q;
    for (auto& [c, d] : indeg) if (d == 0) q.push(c);
    string result;
    while (!q.empty()) {
        char c = q.front(); q.pop(); result += c;
        for (char n : adj[c]) if (--indeg[n] == 0) q.push(n);
    }
    return result.size() == indeg.size() ? result : "";
}
